#include <bits/stdc++.h>
using namespace std;

class PaymentException : public exception {
    string message;
public:
    PaymentException(const string& msg, const exception* cause = nullptr) {
        message = msg;
        if (cause) message += " (caused by: " + string(cause->what()) + ")";
    }
    const char* what() const noexcept override { return message.c_str(); }
};

class PaymentService {
public:
    void process(const string& file) {
        try {
            try {
                string data = readFile(file);
                parseAndPay(data);
            } catch (const runtime_error& e) {
                throw PaymentException("Could not read payment file", &e);
            } catch (const invalid_argument& e) {
                throw PaymentException("Malformed payment data", &e);
            }
        } catch (...) {
            // C++ has no finally keyword; RAII (destructor based cleanup) is the
            // idiomatic replacement, this catch-and-rethrow just simulates "always runs"
            cleanupResources();
            throw;
        }
        cleanupResources();
    }

private:
    string readFile(const string& path) { return "42"; }
    void parseAndPay(const string& data) { stoi(data); cout << "Paid amount: " << data << endl; }
    void cleanupResources() { cout << "Resources cleaned up" << endl; }
};

