class PaymentException(Exception):
    def __init__(self, error_code, message, cause=None):
        super().__init__(message)
        self.error_code = error_code
        self.__cause__ = cause


# Checked vs unchecked is a Java only distinction; in Python every exception
# is handled the same way, the split below is purely by NAMING convention

class CardDeclinedException(PaymentException):
    def __init__(self, reason):
        super().__init__("CARD_DECLINED", reason)


class PaymentAlreadyRefundedException(PaymentException):
    def __init__(self, transaction_id):
        super().__init__("ALREADY_REFUNDED", f"Transaction {transaction_id} was already refunded")


class GatewayTimeoutException(PaymentException):
    def __init__(self, cause):
        super().__init__("GATEWAY_TIMEOUT", "Payment gateway did not respond in time", cause)


class InvalidTransactionStateException(Exception):
    pass


class Order:
    def __init__(self, amount):
        self.amount = amount


class GatewayResponse:
    def __init__(self, declined, decline_reason):
        self.declined = declined
        self.decline_reason = decline_reason


class Gateway:
    def charge(self, order):
        return GatewayResponse(order.amount > 1000, "amount over limit")


class PaymentProcessor:
    def __init__(self):
        self.gateway = Gateway()

    def charge(self, order):
        if order.amount <= 0:
            # an order should never reach here with a non positive amount, that is a bug
            raise InvalidTransactionStateException(f"Order amount must be positive: {order.amount}")

        response = self.gateway.charge(order)
        if response.declined:
            raise CardDeclinedException(response.decline_reason)


def notify_customer(msg):
    print(f"Notify customer: {msg}")


def log_and_flag_for_review(e):
    print(f"Flagged for review: {e}")


