import java.net.SocketTimeoutException;

// Base class for anything related to payment processing
abstract class PaymentException extends Exception {
    private final String errorCode;

    protected PaymentException(String errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }

    protected PaymentException(String errorCode, String message, Throwable cause) {
        super(message, cause);
        this.errorCode = errorCode;
    }

    public String getErrorCode() { return errorCode; }
}

// Checked: expected, recoverable business failures
class CardDeclinedException extends PaymentException {
    CardDeclinedException(String reason) {
        super("CARD_DECLINED", reason);
    }
}

class PaymentAlreadyRefundedException extends PaymentException {
    PaymentAlreadyRefundedException(String transactionId) {
        super("ALREADY_REFUNDED", "Transaction " + transactionId + " was already refunded");
    }
}

class GatewayTimeoutException extends PaymentException {
    GatewayTimeoutException(Throwable cause) {
        super("GATEWAY_TIMEOUT", "Payment gateway did not respond in time", cause);
    }
}

// Unchecked: programming errors and invalid internal state
class InvalidTransactionStateException extends RuntimeException {
    InvalidTransactionStateException(String message) {
        super(message);
    }
}

class Order {
    private double amount;
    Order(double amount) { this.amount = amount; }
    double getAmount() { return amount; }
}

class GatewayResponse {
    private boolean declined;
    private String declineReason;
    GatewayResponse(boolean declined, String declineReason) {
        this.declined = declined;
        this.declineReason = declineReason;
    }
    boolean isDeclined() { return declined; }
    String getDeclineReason() { return declineReason; }
}

class Gateway {
    GatewayResponse charge(Order order) {
        return new GatewayResponse(order.getAmount() > 1000, "amount over limit");
    }
}

class PaymentProcessor {
    private Gateway gateway = new Gateway();

    void charge(Order order) throws CardDeclinedException, PaymentAlreadyRefundedException, GatewayTimeoutException {

        if (order.getAmount() <= 0) {
            // an order should never reach here with a non positive amount, that is a bug
            throw new InvalidTransactionStateException("Order amount must be positive: " + order.getAmount());
        }

        try {
            GatewayResponse response = gateway.charge(order);
            if (response.isDeclined()) {
                throw new CardDeclinedException(response.getDeclineReason());
            }
        } catch (SocketTimeoutException e) {
            throw new GatewayTimeoutException(e);
        }
    }
}

public class Main {
    static void notifyCustomer(String msg) { System.out.println("Notify customer: " + msg); }
    static void logAndFlagForReview(Exception e) { System.out.println("Flagged for review: " + e.getMessage()); }
    static void scheduleRetry(Order order) { System.out.println("Retry scheduled for order of $" + order.getAmount()); }

    public static void main(String[] args) {
        PaymentProcessor processor = new PaymentProcessor();
        Order order = new Order(1500);

        // calling code decides how to react to each expected business failure
        try {
            processor.charge(order);
        } catch (CardDeclinedException e) {
            notifyCustomer(e.getMessage());
        } catch (PaymentAlreadyRefundedException e) {
            logAndFlagForReview(e);
        } catch (GatewayTimeoutException e) {
            scheduleRetry(order);
        }
    }
}

