#include <bits/stdc++.h>
using namespace std;

// Base class for anything related to payment processing
class PaymentException : public exception {
    string errorCode;
    string message;
public:
    PaymentException(const string& errorCode, const string& message) : errorCode(errorCode), message(message) {}
    const char* what() const noexcept override { return message.c_str(); }
    string getErrorCode() const { return errorCode; }
};

class CardDeclinedException : public PaymentException {
public:
    CardDeclinedException(const string& reason) : PaymentException("CARD_DECLINED", reason) {}
};

class PaymentAlreadyRefundedException : public PaymentException {
public:
    PaymentAlreadyRefundedException(const string& transactionId)
        : PaymentException("ALREADY_REFUNDED", "Transaction " + transactionId + " was already refunded") {}
};

class GatewayTimeoutException : public PaymentException {
public:
    GatewayTimeoutException() : PaymentException("GATEWAY_TIMEOUT", "Payment gateway did not respond in time") {}
};

// C++ has no checked/unchecked split either; nothing here is enforced by the compiler
class InvalidTransactionStateException : public exception {
    string message;
public:
    InvalidTransactionStateException(const string& msg) : message(msg) {}
    const char* what() const noexcept override { return message.c_str(); }
};

class Order {
public:
    double amount;
    Order(double amount) : amount(amount) {}
};

class GatewayResponse {
public:
    bool declined;
    string declineReason;
    GatewayResponse(bool declined, string declineReason) : declined(declined), declineReason(declineReason) {}
};

class Gateway {
public:
    GatewayResponse charge(const Order& order) {
        return GatewayResponse(order.amount > 1000, "amount over limit");
    }
};

class PaymentProcessor {
    Gateway gateway;
public:
    void charge(const Order& order) {
        if (order.amount <= 0) {
            // an order should never reach here with a non positive amount, that is a bug
            throw InvalidTransactionStateException("Order amount must be positive: " + to_string(order.amount));
        }

        GatewayResponse response = gateway.charge(order);
        if (response.declined) {
            throw CardDeclinedException(response.declineReason);
        }
    }
};

void notifyCustomer(const string& msg) { cout << "Notify customer: " << msg << endl; }
void logAndFlagForReview(const exception& e) { cout << "Flagged for review: " << e.what() << endl; }
void scheduleRetry(const Order& order) { cout << "Retry scheduled for order of $" << order.amount << endl; }

int main() {
    PaymentProcessor processor;
    Order order(1500);

    // calling code decides how to react to each expected business failure
    try {
        processor.charge(order);
    } catch (const CardDeclinedException& e) {
        notifyCustomer(e.what());
    } catch (const PaymentAlreadyRefundedException& e) {
        logAndFlagForReview(e);
    } catch (const GatewayTimeoutException& e) {
        scheduleRetry(order);
    }
    return 0;
}
